INSERT INTO cms.portfolio_item (id, category_id, slug, title_en, title_ar, client_name, year, subtitle_en, subtitle_ar, price, price_note_en, price_note_ar, external_url, location) VALUES ('port-1', 'pcat-cms-1', 'zayed-group-case-1', 'Salman City Multi-Modal Logistics Complex', 'تطوير المجمع اللوجستي متعدد الوسائط بسلمان الصناعية', 'Al-Jazeera Gulf Holdings W.L.L.', 2025, 'Delivered for Al-Jazeera Gulf Holdings W.L.L. across Manama with measurable SLA benchmarks.', 'تم التنفيذ لصالح مجموعة الجزيرة الخليجية القابضة في Manama وفق أعلى معايير الجودة والالتزام.', 5000, 'Turnkey scope including 10% NBR VAT compliance (BHD)', 'باقة تنفيذ متكاملة شاملة التقارير وضريبة القيمة المضافة', 'https://zayedgroup.bh/work/zayed-group-case-1', 'Manama, Bahrain') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.article (id, slug, title_en, title_ar, excerpt_en, excerpt_ar, body_en, body_ar, body_html_en, body_html_ar, cover_url, seo_title_en, seo_title_ar, seo_description_en, seo_description_ar, category, tags, author_name, status, publish_at, featured, created_at, updated_at) VALUES ('art-1', 'zayed-group-2026-outlook', 'Zayed Group 2026 GCC Market Outlook & Benchmarks', 'توقعات أسواق الخليج ومعايير الأداء لعام 2026 — مجموعة زايد', 'Key operational benchmarks, real metrics, and 2026 guidance from Zayed Group in Manama.', 'أبرز المعايير التشغيلية والأرقام الموثقة وإرشادات 2026 من مجموعة زايد في Manama.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Diversified Bahraini holding group operating retail storefronts, last-mile fleet logistics, media production, and enterprise advisory. Focusing on Enterprise Turnkey Operations Retainer, our teams help Gulf enterprises scale reliably."}]}]}'::jsonb, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"مجموعة بحرينية متنوعة الأنشطة تدير المتاجر الإلكترونية والأسطول اللوجستي والإنتاج الإعلامي والاستشارات. من خلال خدمة إدارة العمليات المؤسسية الشاملة نساعد المؤسسات على النمو المستدام."}]}]}'::jsonb, '<p>Diversified Bahraini holding group operating retail storefronts, last-mile fleet logistics, media production, and enterprise advisory.</p><p>Focusing on <strong>Enterprise Turnkey Operations Retainer</strong>, our Manama specialists help Gulf organizations standardize turnaround times and audit transparency.</p>', '<p>مجموعة بحرينية متنوعة الأنشطة تدير المتاجر الإلكترونية والأسطول اللوجستي والإنتاج الإعلامي والاستشارات.</p><p>من خلال خدمة <strong>إدارة العمليات المؤسسية الشاملة</strong>، يعمل فريقنا في Manama على توحيد سرعة التسليم ووضوح التدقيق.</p>', '/api/files/media/banners/banner-01.png', 'Zayed Group 2026 GCC Market Outlook & Benchmarks | Zayed Group', 'توقعات أسواق الخليج ومعايير الأداء لعام 2026 — مجموعة زايد | مجموعة زايد', 'Executive guide by Zayed Group covering Enterprise Turnkey Operations Retainer benchmarks in Bahrain.', 'دليل تنفيذي من مجموعة زايد حول معايير إدارة العمليات المؤسسية الشاملة في البحرين.', 'Insights', '{"all","insights","Manama","2026"}'::text[], 'Hana Yousef', 'published', now() - interval '6 days', true, now() - interval '6 days', now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.faq (id, question_en, question_ar, answer_en, answer_ar, category, is_published, sort_order, created_at) VALUES ('faq-1', 'How quickly can Zayed Group initiate a Enterprise Turnkey Operations Retainer engagement?', 'كم يستغرق بدء تنفيذ خدمة إدارة العمليات المؤسسية الشاملة لدى مجموعة زايد؟', 'Discovery and kickoff begin within 48 hours of quotation sign-off, with a dedicated lead assigned in Manama.', 'يبدأ التخطيط والتنفيذ خلال 48 ساعة من اعتماد عرض السعر مع تعيين مدير حساب مخصص في Manama.', 'services', true, 1, now() - interval '45 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.portfolio_item (id, category_id, slug, title_en, title_ar, client_name, year, subtitle_en, subtitle_ar, price, price_note_en, price_note_ar, external_url, location) VALUES ('port-2', 'pcat-cms-2', 'zayed-group-case-2', 'Bahrain Bay Sovereign Data & Operations Wing', 'تأسيس مركز البيانات والعمليات بخليج البحرين', 'Bahrain Bay Hospitality Group', 2026, 'Delivered for Bahrain Bay Hospitality Group across Manama with measurable SLA benchmarks.', 'تم التنفيذ لصالح مجموعة خليج البحرين للضيافة في Manama وفق أعلى معايير الجودة والالتزام.', 5400, 'Turnkey scope including 10% NBR VAT compliance (BHD)', 'باقة تنفيذ متكاملة شاملة التقارير وضريبة القيمة المضافة', 'https://zayedgroup.bh/work/zayed-group-case-2', 'Manama, Bahrain') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.article (id, slug, title_en, title_ar, excerpt_en, excerpt_ar, body_en, body_ar, body_html_en, body_html_ar, cover_url, seo_title_en, seo_title_ar, seo_description_en, seo_description_ar, category, tags, author_name, status, publish_at, featured, created_at, updated_at) VALUES ('art-2', 'zayed-group-service-standards', 'Inside Our Advisory SLA: Speed, Quality & Auditability', 'معايير اتفاقية مستوى الخدمة والجودة في إدارة العمليات المؤسسية الشاملة', 'Key operational benchmarks, real metrics, and 2026 guidance from Zayed Group in Manama.', 'أبرز المعايير التشغيلية والأرقام الموثقة وإرشادات 2026 من مجموعة زايد في Manama.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Diversified Bahraini holding group operating retail storefronts, last-mile fleet logistics, media production, and enterprise advisory. Focusing on Commercial Media Production, our teams help Gulf enterprises scale reliably."}]}]}'::jsonb, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"مجموعة بحرينية متنوعة الأنشطة تدير المتاجر الإلكترونية والأسطول اللوجستي والإنتاج الإعلامي والاستشارات. من خلال خدمة إنتاج إعلامي وتجاري متكامل نساعد المؤسسات على النمو المستدام."}]}]}'::jsonb, '<p>Diversified Bahraini holding group operating retail storefronts, last-mile fleet logistics, media production, and enterprise advisory.</p><p>Focusing on <strong>Commercial Media Production</strong>, our Manama specialists help Gulf organizations standardize turnaround times and audit transparency.</p>', '<p>مجموعة بحرينية متنوعة الأنشطة تدير المتاجر الإلكترونية والأسطول اللوجستي والإنتاج الإعلامي والاستشارات.</p><p>من خلال خدمة <strong>إنتاج إعلامي وتجاري متكامل</strong>، يعمل فريقنا في Manama على توحيد سرعة التسليم ووضوح التدقيق.</p>', '/api/files/media/banners/banner-02.png', 'Inside Our Advisory SLA: Speed, Quality & Auditability | Zayed Group', 'معايير اتفاقية مستوى الخدمة والجودة في إدارة العمليات المؤسسية الشاملة | مجموعة زايد', 'Executive guide by Zayed Group covering Commercial Media Production benchmarks in Bahrain.', 'دليل تنفيذي من مجموعة زايد حول معايير إنتاج إعلامي وتجاري متكامل في البحرين.', 'Operations', '{"all","operations","Manama","2026"}'::text[], 'Bader Ali', 'published', now() - interval '12 days', true, now() - interval '12 days', now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.faq (id, question_en, question_ar, answer_en, answer_ar, category, is_published, sort_order, created_at) VALUES ('faq-2', 'Do all invoices include Bahrain NBR 10% VAT and Arabic breakdown?', 'هل تشمل الفواتير ضريبة القيمة المضافة 10% والتفصيل باللغتين؟', 'Yes. Every tax invoice is issued in BHD under CR CR-100001-1 and VAT ID 200010000100002 with itemized bilingual lines.', 'نعم، تصدر جميع الفواتير الضريبية بعملة BHD وفق السجل CR-100001-1 والرقم الضريبي 200010000100002.', 'billing', true, 2, now() - interval '45 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.portfolio_item (id, category_id, slug, title_en, title_ar, client_name, year, subtitle_en, subtitle_ar, price, price_note_en, price_note_ar, external_url, location) VALUES ('port-3', 'pcat-cms-3', 'zayed-group-case-3', '15-MW Rooftop Solar Across Group Factories', 'تركيب ألواح شمسية بقدرة 15 ميجاواط بالمصانع', 'Dilmun Energy Partners', 2025, 'Delivered for Dilmun Energy Partners across Manama with measurable SLA benchmarks.', 'تم التنفيذ لصالح شركاء دلمون للطاقة في Manama وفق أعلى معايير الجودة والالتزام.', 950, 'Turnkey scope including 10% NBR VAT compliance (BHD)', 'باقة تنفيذ متكاملة شاملة التقارير وضريبة القيمة المضافة', 'https://zayedgroup.bh/work/zayed-group-case-3', 'Manama, Bahrain') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.article (id, slug, title_en, title_ar, excerpt_en, excerpt_ar, body_en, body_ar, body_html_en, body_html_ar, cover_url, seo_title_en, seo_title_ar, seo_description_en, seo_description_ar, category, tags, author_name, status, publish_at, featured, created_at, updated_at) VALUES ('art-3', 'zayed-group-arabic-bilingual-ops', 'Why True Arabic-First Workflows Matter in Bahrain Enterprises', 'أهمية تدفقات العمل العربية المتكاملة في مؤسسات البحرين', 'Key operational benchmarks, real metrics, and 2026 guidance from Zayed Group in Manama.', 'أبرز المعايير التشغيلية والأرقام الموثقة وإرشادات 2026 من مجموعة زايد في Manama.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Diversified Bahraini holding group operating retail storefronts, last-mile fleet logistics, media production, and enterprise advisory. Focusing on Dedicated Fleet Distribution, our teams help Gulf enterprises scale reliably."}]}]}'::jsonb, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"مجموعة بحرينية متنوعة الأنشطة تدير المتاجر الإلكترونية والأسطول اللوجستي والإنتاج الإعلامي والاستشارات. من خلال خدمة توزيع مخصص عبر أسطول المجموعة نساعد المؤسسات على النمو المستدام."}]}]}'::jsonb, '<p>Diversified Bahraini holding group operating retail storefronts, last-mile fleet logistics, media production, and enterprise advisory.</p><p>Focusing on <strong>Dedicated Fleet Distribution</strong>, our Manama specialists help Gulf organizations standardize turnaround times and audit transparency.</p>', '<p>مجموعة بحرينية متنوعة الأنشطة تدير المتاجر الإلكترونية والأسطول اللوجستي والإنتاج الإعلامي والاستشارات.</p><p>من خلال خدمة <strong>توزيع مخصص عبر أسطول المجموعة</strong>، يعمل فريقنا في Manama على توحيد سرعة التسليم ووضوح التدقيق.</p>', '/api/files/media/banners/banner-03.png', 'Why True Arabic-First Workflows Matter in Bahrain Enterprises | Zayed Group', 'أهمية تدفقات العمل العربية المتكاملة في مؤسسات البحرين | مجموعة زايد', 'Executive guide by Zayed Group covering Dedicated Fleet Distribution benchmarks in Bahrain.', 'دليل تنفيذي من مجموعة زايد حول معايير توزيع مخصص عبر أسطول المجموعة في البحرين.', 'Governance', '{"all","governance","Manama","2026"}'::text[], 'Hana Yousef', 'published', now() - interval '18 days', true, now() - interval '18 days', now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.faq (id, question_en, question_ar, answer_en, answer_ar, category, is_published, sort_order, created_at) VALUES ('faq-3', 'Which corporate payment channels do you support?', 'ما هي قنوات الدفع المؤسسية المتاحة لديكم؟', 'We accept National Bank of Bahrain (NBB) corporate wire/IBAN, BenefitPay, corporate cards, and approved 30-day credit terms.', 'نقبل التحويل البنكي المباشر لحساب National Bank of Bahrain (NBB) وبنفت باي والبطاقات وفترات الائتمان 30 يوماً.', 'payments', true, 3, now() - interval '45 days') ON CONFLICT (id) DO NOTHING;
