INSERT INTO cms.website_content (id, draft, published, previous, revision, published_at, updated_at) VALUES ('main', '{"company":{"nameEn":"Zayed Diversified Group W.L.L.","nameAr":"مجموعة زايد المتنوعة ذ.م.م","shortEn":"Zayed Group","shortAr":"مجموعة زايد","taglineEn":"Multi-Division Commerce, Services, Media & Enterprise Operations","taglineAr":"مجموعة متعددة الأنشطة في التجارة والخدمات والإعلام والعمليات","aboutEn":"Diversified Bahraini holding group operating retail storefronts, last-mile fleet logistics, media production, and enterprise advisory.","aboutAr":"مجموعة بحرينية متنوعة الأنشطة تدير المتاجر الإلكترونية والأسطول اللوجستي والإنتاج الإعلامي والاستشارات."},"hero":{"titleEn":"Zayed Group — Multi-Division Commerce, Services, Media & Enterprise Operations","titleAr":"مجموعة زايد — مجموعة متعددة الأنشطة في التجارة والخدمات والإعلام والعمليات","ctaLabelEn":"Explore Zayed Group","ctaLabelAr":"استكشف مجموعة زايد"},"featuredServices":[{"code":"SVC-ENT","en":"Enterprise Turnkey Operations Retainer","ar":"إدارة العمليات المؤسسية الشاملة","rate":2500},{"code":"SVC-PRD","en":"Commercial Media Production","ar":"إنتاج إعلامي وتجاري متكامل","rate":1800},{"code":"SVC-LOG","en":"Dedicated Fleet Distribution","ar":"توزيع مخصص عبر أسطول المجموعة","rate":950},{"code":"ZAY-CON","en":"Turnkey Commercial EPC & Fit-Out","ar":"المقاولات الهندسية والتجهيز المكتبي المتكامل","rate":4800}]}'::jsonb, '{"company":{"nameEn":"Zayed Diversified Group W.L.L.","nameAr":"مجموعة زايد المتنوعة ذ.م.م","shortEn":"Zayed Group","shortAr":"مجموعة زايد","taglineEn":"Multi-Division Commerce, Services, Media & Enterprise Operations","taglineAr":"مجموعة متعددة الأنشطة في التجارة والخدمات والإعلام والعمليات","aboutEn":"Diversified Bahraini holding group operating retail storefronts, last-mile fleet logistics, media production, and enterprise advisory.","aboutAr":"مجموعة بحرينية متنوعة الأنشطة تدير المتاجر الإلكترونية والأسطول اللوجستي والإنتاج الإعلامي والاستشارات."},"hero":{"titleEn":"Zayed Group — Mul